    r={'quantity':q,'value':v,'confidence':c,'evidence':e}
    if t:r['target']=t
    if u:r['uncertainty']=u
    if unit:r['unit']=unit
    if a:r['assumptions']=[{'name':k,'value':x} for k,x in a]
